using CustomCodeFramework.Core.Pagination;using CustomCodeFramework.Cqrs.Dispatching;using Dhole.Content.Api.Authorization;using Dhole.Content.Api.Extensions;using Dhole.Content.Application.ContentItems.ArchiveContent;using Dhole.Content.Application.ContentItems.CreateContentItem;using Dhole.Content.Application.ContentItems.DeleteContent;using Dhole.Content.Application.ContentItems.GetContentItemById;using Dhole.Content.Application.ContentItems.GetContentItems;using Dhole.Content.Application.ContentItems.GetContentRevisions;using Dhole.Content.Application.ContentItems.PublishContent;using Dhole.Content.Application.ContentItems.RestoreContentRevision;using Dhole.Content.Application.ContentItems.ScheduleContent;using Dhole.Content.Application.ContentItems.SubmitContentForReview;using Dhole.Content.Application.ContentItems.UnpublishContent;using Dhole.Content.Application.ContentItems.UpdateContentItem;using Dhole.Content.Contracts.ContentItems;using Dhole.Content.Domain.ContentItems.Enums;namespace Dhole.Content.Api.Endpoints;
public static class ContentItemEndpoints
{public static IEndpointRouteBuilder MapContentItemEndpoints(this IEndpointRouteBuilder app){var g=app.MapGroup("/api/content/items").WithTags("Content Items").RequireAuthorization();g.MapGet("/",async(int? pageNumber,int? pageSize,string? siteKey,string? type,string? status,string? search,string? locale,IQueryDispatcher d,CancellationToken ct)=>{ContentType? t=Enum.TryParse<ContentType>(type,true,out var tv)?tv:null;ContentStatus? s=Enum.TryParse<ContentStatus>(status,true,out var sv)?sv:null;var r=await d.DispatchAsync(new GetContentItemsQuery(PageRequest.Create(pageNumber??1,pageSize??25),siteKey,t,s,search,locale),ct);return EndpointResults.FromPaged(r);}).RequireScope(ContentScopeNames.View);g.MapGet("/{id:guid}",async(Guid id,IQueryDispatcher d,HttpContext h,CancellationToken ct)=>EndpointResults.FromResult(await d.DispatchAsync(new GetContentItemByIdQuery(id),ct),h)).RequireScope(ContentScopeNames.View);g.MapPost("/",async(CreateContentItemRequest r,ICommandDispatcher d,HttpContext h,CancellationToken ct)=>{var seo=r.Seo;var result=await d.DispatchAsync(new CreateContentItemCommand(r.Type,r.Title,r.Slug,r.Excerpt,r.BlocksJson??"[]",r.RenderedHtml,r.FeaturedMediaId,r.AuthorUserId,r.Locale,r.SortOrder,r.IsFeatured,r.TaxonomyTermIds??[],seo?.Title,seo?.Description,seo?.Keywords,seo?.CanonicalUrl,seo?.Robots,seo?.OpenGraphMediaId,seo?.StructuredDataJson,r.SiteKey,h.GetCurrentUserId()),ct);return EndpointResults.FromResult(result,h);}).RequireScope(ContentScopeNames.Create);g.MapPut("/{id:guid}",async(Guid id,UpdateContentItemRequest r,ICommandDispatcher d,HttpContext h,CancellationToken ct)=>{var seo=r.Seo;return EndpointResults.FromResult(await d.DispatchAsync(new UpdateContentItemCommand(id,r.Title,r.Slug,r.Excerpt,r.BlocksJson??"[]",r.RenderedHtml,r.FeaturedMediaId,r.Locale,r.SortOrder,r.IsFeatured,r.TaxonomyTermIds??[],seo?.Title,seo?.Description,seo?.Keywords,seo?.CanonicalUrl,seo?.Robots,seo?.OpenGraphMediaId,seo?.StructuredDataJson,h.GetCurrentUserId()),ct),h);}).RequireScope(ContentScopeNames.Edit);g.MapPost("/{id:guid}/review",async(Guid id,ICommandDispatcher d,HttpContext h,CancellationToken ct)=>EndpointResults.FromResult(await d.DispatchAsync(new SubmitContentForReviewCommand(id,h.GetCurrentUserId()),ct),h)).RequireScope(ContentScopeNames.Edit);g.MapPost("/{id:guid}/publish",async(Guid id,ICommandDispatcher d,HttpContext h,CancellationToken ct)=>EndpointResults.FromResult(await d.DispatchAsync(new PublishContentCommand(id,h.GetCurrentUserId()),ct),h)).RequireScope(ContentScopeNames.Publish);g.MapPost("/{id:guid}/schedule",async(Guid id,ScheduleContentRequest r,ICommandDispatcher d,HttpContext h,CancellationToken ct)=>EndpointResults.FromResult(await d.DispatchAsync(new ScheduleContentCommand(id,r.ScheduledAtUtc,h.GetCurrentUserId()),ct),h)).RequireScope(ContentScopeNames.Publish);g.MapPost("/{id:guid}/unpublish",async(Guid id,ICommandDispatcher d,HttpContext h,CancellationToken ct)=>EndpointResults.FromResult(await d.DispatchAsync(new UnpublishContentCommand(id,h.GetCurrentUserId()),ct),h)).RequireScope(ContentScopeNames.Publish);g.MapPost("/{id:guid}/archive",async(Guid id,ICommandDispatcher d,HttpContext h,CancellationToken ct)=>EndpointResults.FromResult(await d.DispatchAsync(new ArchiveContentCommand(id,h.GetCurrentUserId()),ct),h)).RequireScope(ContentScopeNames.Edit);g.MapDelete("/{id:guid}",async(Guid id,ICommandDispatcher d,HttpContext h,CancellationToken ct)=>EndpointResults.FromResult(await d.DispatchAsync(new DeleteContentCommand(id,h.GetCurrentUserId()),ct),h)).RequireScope(ContentScopeNames.Delete);g.MapGet("/{id:guid}/revisions",async(Guid id,IQueryDispatcher d,CancellationToken ct)=>EndpointResults.Ok(await d.DispatchAsync(new GetContentRevisionsQuery(id),ct))).RequireScope(ContentScopeNames.View);g.MapPost("/{id:guid}/revisions/{revisionId:guid}/restore",async(Guid id,Guid revisionId,RestoreContentRevisionRequest r,ICommandDispatcher d,HttpContext h,CancellationToken ct)=>EndpointResults.FromResult(await d.DispatchAsync(new RestoreContentRevisionCommand(id,revisionId,r.Reason,h.GetCurrentUserId()),ct),h)).RequireScope(ContentScopeNames.Edit);return app;}}
